def resolve(path, cwd, links):
    if cwd is None:
        return None

    # Count symlinks followed to prevent infinite loops
    link_count = [0]

    def resolve_helper(current_path, remaining_components):
        if link_count[0] > 8:
            return None

        if not remaining_components:
            return current_path

        component = remaining_components[0]
        rest = remaining_components[1:]

        # Skip empty components and '.'
        if component == '' or component == '.':
            return resolve_helper(current_path, rest)

        # Handle '..'
        if component == '..':
            if current_path == '/':
                return resolve_helper('/', rest)
            else:
                parent = current_path.rsplit('/', 1)[0]
                if parent == '':
                    parent = '/'
                return resolve_helper(parent, rest)

        # Append component to current path
        if current_path == '/':
            new_path = '/' + component
        else:
            new_path = current_path + '/' + component

        # Check if this path is a symlink
        if new_path in links:
            link_count[0] += 1
            if link_count[0] > 8:
                return None

            target = links[new_path]

            # If target is absolute, start from root; otherwise, start from parent directory
            if target.startswith('/'):
                target_base = '/'
                target_components = [c for c in target.split('/') if c]
            else:
                # Target is relative to the directory containing the link
                link_dir = current_path.rsplit('/', 1)[0]
                if link_dir == '':
                    link_dir = '/'
                target_base = link_dir
                target_components = [c for c in target.split('/') if c]

            # Resolve the target first, then continue with remaining components
            resolved_target = resolve_helper(target_base, target_components)
            if resolved_target is None:
                return None

            return resolve_helper(resolved_target, rest)

        # Not a symlink, continue
        return resolve_helper(new_path, rest)

    # Parse the input path
    if path.startswith('/'):
        base = '/'
        components = [c for c in path.split('/') if c]
    else:
        base = cwd
        components = [c for c in path.split('/') if c]

    result = resolve_helper(base, components)

    # Ensure no trailing slash except for '/'
    if result and result != '/':
        result = result.rstrip('/')

    return result

